def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    last_me, last_opp = history[-1]
    recent_opp = opp[-10:]
    recent_c = recent_opp.count('C')
    recent_d = len(recent_opp) - recent_c

    if n < 4:
        return 'C'

    if n >= 90:
        if recent_d <= 1:
            return 'C'
        return 'D'

    if opp_d == 0:
        if n == 50:
            return 'D'
        if n >= 70 and n % 9 == 0:
            return 'D'
        return 'C'

    if recent_d >= 8:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            run = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    run += 1
                else:
                    break
            if run >= 3 and rng.random() < 0.35:
                return 'C'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        else:
            if recent_d >= 3:
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    if recent_c >= 9:
        if n >= 60 and n % 13 == 0:
            return 'D'
        return 'C'

    if recent_c >= 6:
        return 'C'

    if recent_c >= 3:
        if opp_c * 2 >= n:
            return 'C'
        return 'D'

    if rng.random() < 0.1:
        return 'C'
    return 'D'
